    /// <summary>
    /// validateField
    /// </summary>
    /// <param name = "_fieldIdToCheck">_fieldIdToCheck</param>
    /// <returns>Result</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        switch(_fieldIdToCheck)
        {
            case fieldNum(METSalesOrderGuideItem, ReferenceType):
                if(this.Type == METSalesOrderGuideType::DoNotSellTo
                && this.ReferenceType == METSalesOrderGuideReferenceType::Site)
                {
                    ret = checkFailed(strFmt("@MET:SalesOrderGuideInvalidSelectionForDoNotSell", this.ReferenceType));
                    this.ReferenceType = METSalesOrderGuideReferenceType::Customer;
                }
                break;
        }
    
        return ret;
    }

    /// <summary>
    /// modifiedField
    /// </summary>
    /// <param name = "_fieldId">_fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(METSalesOrderGuideItem, ReferenceType):
                this.Reference          = '';
                //this.CountryRegionId    = '';
                break;

            case fieldNum(METSalesOrderGuideItem, Reference):
                this.modifiedReference();
                break;
                
        }
    }

    /// <summary>
    /// logic on modify Reference field
    /// </summary>
    void modifiedReference()
    {
        switch(this.ReferenceType)
        {
            case METSalesOrderGuideReferenceType::CustomerOperationsGroup:
                this.CustomerOperationsGroup = this.Reference;
                this.Customer = '';
                this.Site = '';
                this.State = '';
                break;

            case METSalesOrderGuideReferenceType::Customer:
                this.CustomerOperationsGroup = '';
                this.Customer = this.Reference;
                this.Site = '';
                this.State = '';
                break;

            case METSalesOrderGuideReferenceType::Site:
                this.CustomerOperationsGroup = '';
                this.Customer = '';
                this.Site = this.Reference;
                this.State = '';
                break;

            case METSalesOrderGuideReferenceType::State:
                this.CustomerOperationsGroup = '';
                this.Customer = '';
                this.Site = '';
                this.State = this.Reference;
                break;
        }
    }

    /// <summary>
    /// Find a record
    /// </summary>
    /// <param name = "_itemId">Item</param>
    /// <param name = "_referenceType">Reference type</param>
    /// <param name = "_reference">Reference</param>
    /// <param name = "_guideType">Guide type</param>
    /// <param name = "_forUpdate">Update</param>
    /// <returns>Record if found</returns>
    static METSalesOrderGuideItem find( ItemId                          _itemId, 
                                        METSalesOrderGuideReferenceType _referenceType,
                                        METSalesOrderGuideReference     _reference,
                                        METSalesOrderGuideType          _guideType,
                                        boolean                         _forUpdate = false)
    {
        METSalesOrderGuideItem salesOrderGuideItem;

        if(_itemId && _reference)
        {
            if(_forUpdate)
            {
                salesOrderGuideItem.selectForUpdate(_forUpdate);
            }

            select firstonly salesOrderGuideItem
                where   salesOrderGuideItem.ItemId          == _itemId
                &&      salesOrderGuideItem.ReferenceType   == _referenceType
                &&      salesOrderGuideItem.Reference       == _reference
                &&      salesOrderGuideItem.Type            == _guideType;
        }

        return salesOrderGuideItem;
    }

/// <summary>
/// Does a record exist for a given Item
/// </summary>
/// <param name = "_itemId">Item id</param>
/// <param name = "_includeExclude">Include Exclude flag</param>
/// <returns>True if found</returns>
static boolean existForItem(ItemId _itemId, METSalesOrderGuideType _guideType)
{
    return _itemId
    &&  (select firstOnly ItemId
            from METSalesOrderGuideItem
            where   METSalesOrderGuideItem.ItemId   == _itemId
            &&      METSalesOrderGuideItem.Type     == _guideType).RecId != 0;
}

/// <summary>
/// Does a record exist for a given refernce
/// </summary>
/// <param name = "_referenceType">Reference type</param>
/// <param name = "_reference">Reference</param>
/// <param name = "_guideType">Guide type</param>
/// <returns>True if found</returns>
static boolean existForReference(METSalesOrderGuideReferenceType _referenceType,
                                 METSalesOrderGuideReference     _reference,
                                 METSalesOrderGuideType          _guideType)
{
    return _reference
    &&  (select firstOnly RecId
            from METSalesOrderGuideItem
            where   METSalesOrderGuideItem.ReferenceType   == _referenceType
            &&      METSalesOrderGuideItem.Reference       == _reference
            &&      METSalesOrderGuideItem.Type            == _guideType).RecId != 0;
}

/// <summary>
/// Does a record exist
/// </summary>
/// <param name = "_itemId">Item id</param>
/// <param name = "_referenceType">Reference type</param>
/// <param name = "_reference">Reference</param>
/// <param name = "_guideType">Guide type</param>
/// <returns>True if found</returns>
static boolean exist(   ItemId                          _itemId, 
                        METSalesOrderGuideReferenceType _referenceType,
                        METSalesOrderGuideReference     _reference,
                        METSalesOrderGuideType          _guideType)
{
    return _itemId && _reference
    &&  (select firstOnly RecId
            from METSalesOrderGuideItem
            where   METSalesOrderGuideItem.ItemId          == _itemId
            &&      METSalesOrderGuideItem.ReferenceType   == _referenceType
            &&      METSalesOrderGuideItem.Reference       == _reference
            &&      METSalesOrderGuideItem.Type            == _guideType).RecId != 0;
}

