    /// <summary>
    /// Get the Sales order guide id - number sequence reference
    /// </summary>
    /// <returns>number sequence reference</returns>
    public static NumberSequenceReference numRefMETSalesOrderGuideId()
    {
        return NumberSeqReference::findReference(extendedTypeNum(METSalesOrderGuideId));
    }

    /// <summary>
    /// Get the Sales order guide id - number sequence
    /// </summary>
    /// <returns>number sequence</returns>
    private NumberSeq getSalesOrderGuideIdNumberSeq()
    {
        NumberSequenceReference numberSequenceReference;
        NumberSequenceTable     numberSequenceTable;
        NumberSeq               numberSeq;

        numberSequenceReference = METSalesOrderGuideItem::numRefMETSalesOrderGuideId();
        numberSequenceTable = NumberSequenceTable::find(numberSequenceReference.NumberSequenceId);

        if (numberSequenceTable)
        {
            numberSeq = NumberSeq::newGetNum(numberSequenceReference);
        }

        if (numberSeq == null)
        {
            throw error(strfmt("@GLS111556", new DictType(extendedtypenum(METSalesOrderGuideId)).label(), "@SYS334250"));
        }

        return numberSeq;
    }

/// <summary>
/// Method is overriden to initialize default field values before inserting into the data source table
/// </summary>
public void initValue()
{
    super();
    this.SalesOrderGuideId = this.getSalesOrderGuideIdNumberSeq().num();
}
